sys_variable_value.value:
(function execute(inputs, outputs) {
// ... code ...

var v_date = new GlideDateTime(inputs.visitDate);
var currDate = new GlideDateTime();

var twoHours = 2*60*60*1000;

var v_dateNum = v_date.getNumericValue();
var currDateNum = currDate.getNumericValue();

var isVisited = true;

if(currDateNum > (v_dateNum + twoHours))
{
    isVisited = false;
}

outputs.isvisited = isVisited;


})(inputs, outputs);

